## Implementación en Unity

Guarda el componente como PreparacionEntreRondas.cs y añádelo a un objeto de la escena. Conecta Seleccionar con 1 para escudo y 2 para filtro. En inventario, usa Confirmar para aplicar el equipo pendiente. Muestra Amenaza antes de resolver y usa Preparativos para comparar el coste de menú.

```csharp
using UnityEngine;

public class PreparacionEntreRondas : MonoBehaviour
{
    [SerializeField] bool inventario;
    readonly int[] amenazas = { 1, 2, 1, 3 };
    public int Ronda { get; private set; }
    public int Equipo { get; private set; }
    public int Pendiente { get; private set; }
    public int Preparativos { get; private set; }
    public int Dano { get; private set; }
    public int Amenaza => Ronda < amenazas.Length ? amenazas[Ronda] : 0;

    public void Seleccionar(int pieza)
    {
        if (Amenaza == 0 || (pieza != 1 && pieza != 2)) return;
        if (inventario) Pendiente ^= pieza;
        else Equipo = pieza;
        Preparativos++;
    }

    public void Confirmar()
    {
        if (!inventario || Amenaza == 0 || Pendiente == Equipo) return;
        Equipo = Pendiente;
        Preparativos++;
    }

    public void Resolver()
    {
        if (Amenaza == 0) return;
        int sinCubrir = Amenaza & ~Equipo;
        if ((sinCubrir & 1) != 0) Dano++;
        if ((sinCubrir & 2) != 0) Dano++;
        Ronda++;
    }
}
```

